import numpy as np
from itertools import product

def solve_small(W, s):
    W_prime = W - s + 1
    max_k = 0
    # We can try different values of u_{r,c}
    # Since u_{r,c} can be any non-negative integer, but we only need a few.
    # Let's try u_{r,c} in {0, 1, 2}.
    for u_flat in product([0, 1, 2], repeat=W_prime**2):
        u = np.array(u_flat).reshape((W_prime, W_prime))
        c = np.zeros((W, W), dtype=int)
        for i in range(W):
            for j in range(W):
                # sum u_{r,c} for r in [i-s+1, i] and c in [j-s+1, j]
                # such that 0 <= r < W_prime and 0 <= c < W_prime
                r_min = max(0, i - s + 1)
                r_max = min(i, W_prime - 1)
                c_min = max(0, j - s + 1)
                c_max = min(j, W_prime - 1)
                if r_min <= r_max and c_min <= c_max:
                    c[i, j] = np.sum(u[r_min:r_max+1, c_min:c_max+1])

        counts = {}
        for val in c.flatten():
            if val > 0:
                counts[val] = counts.get(val, 0) + 1

        if counts:
            max_k = max(max_k, max(counts.values()))
    return max_k

