import itertools

def solve_small(n, m):
    # Possible top-left corners of m x m tiles
    corners = []
    for r in range(n - m + 1):
        for c in range(n - m + 1):
            corners.append((r, c))

    # We want to maximize k = max |{ (r,c) : count(r,c) = x }| for x > 0
    # Let x_{i,j} be the number of tiles with top-left corner (i,j)
    # Since we want to maximize k, let's try small values for x_{i,j}
    # Actually, the number of tiles can be large, but we only care about the count.
    # The maximum count is bounded.

    max_k = 0
    # Let's try all possible combinations of x_{i,j} for small cases.
    # This is too many. Let's try a different approach.
    # For a fixed set of tiles, we calculate k.
    # What's the maximum possible k? It's n*n.
    # If k = n*n, then all cells have the same count x.
    # This means x * n*n = N * m*m.
    # Also, each cell (r,c) is covered by x tiles.
    # This is possible if and only if x * I_Board = \sum I_{Tile_i}
    # This is only possible if m divides n (if we want x=1).

    # Let's try a simpler approach:
    # A set of cells R with size k has the same count x.
    # This means x * I_R = \sum_{i=1}^N I_{Tile_i}.
    # This implies that the indicator function of R is a sum of N squares.

    # Let's try to find the maximum k for small n, m by iterating over all possible 
    # configurations of tiles (x_{i,j} \in {0, 1}).
    # For n=3, m=2, there are 2^4 = 16 configurations.

    best_k = 0
    for x_vals in itertools.product([0, 1], repeat=len(corners)):
        counts = [[0]*n for _ in range(n)]
        for idx, x in enumerate(x_vals):
            if x == 1:
                r, c = corners[idx]
                for dr in range(m):
                    for dc in range(m):
                        counts[r+dr][c+dc] += 1

        # Calculate k
        freq = {}
        for r in range(n):
            for c in range(n):
                cnt = counts[r][c]
                if cnt > 0:
                    freq[cnt] = freq.get(cnt, 0) + 1

        if freq:
            best_k = max(best_k, max(freq.values()))

    return best_k

