import numpy as np
from scipy.optimize import linprog

def solve_fixed_k(n, m):
    num_vars = (n - m + 1)**2
    A = np.zeros((n*n, num_vars))

    idx = 0
    for r in range(n - m + 1):
        for c in range(n - m + 1):
            for dr in range(m):
                for dc in range(m):
                    A[ (r+dr)*n + (c+dc), idx ] = 1
            idx += 1

    for x_val in range(1, n*n + 1):
        b = np.full(n*n, x_val)
        # Use linprog to find a non-negative real solution
        res = linprog(np.zeros(num_vars), A_eq=A, b_eq=b, bounds=(0, None), method='highs')
        if res.success:
            # We need an integer solution. Let's try to see if the real solution is integer.
            if np.all(np.isclose(res.x, np.round(res.x), atol=1e-5)):
                return x_val
    return 0

